D.terms=[
{id:"t-pyramid",name:"Пирамида",def:"Каменная гробница фараона в виде рукотворной горы.",ch:"Возносящиеся к небесам пирамиды, как считалось, помогали фараону вернуться к богам и сохраняли его тело.",ties:["giza","egypt"]},
{id:"t-mummy",name:"Мумия и подобие",def:"Бальзамированное тело и каменное изображение, которые должны сохранить жизнь души.",ch:"Египтянам было мало сохранить тело. Скульптор «сохраняет жизнь»: голова фараона из гранита заступает место царя в гробнице.",ties:["egypt","giza"]},
{id:"t-canon",name:"Канон",def:"Набор правил, по которому египетский художник изображал людей, богов и природу.",ch:"Каждый элемент в самом характерном ракурсе; сидящие фигуры держат руки на коленях; облик богов предопределён. Художник учил правила и больше ничего не должен был выдумывать.",ties:["egypt","hesira","nebamun","khnumhotep"]},
{id:"t-style",name:"Стиль",def:"Невидимый закон, которому подчиняются все создания народа в одну эпоху.",ch:"По Гомбриху, стиль трудно объяснить словами, его проще увидеть. Египетский стиль даёт каждому произведению невозмутимую ясность и строгую выверенность форм.",ties:["egypt","akhenaten"]},
{id:"t-hierarchy",name:"Иерархический масштаб",def:"Размер фигуры показывает её значение, а не расстояние.",ch:"Египтяне рисовали своих «боссов» больше слуг и даже жён. Хнумхотеп на росписи крупнее всех остальных.",ties:["khnumhotep"]},
{id:"t-stele",name:"Стела",def:"Вертикальный каменный памятник с изображением и надписью.",ch:"Стела Нарам-Суэна прославляет победу царя и должна была держать побеждённых в покорности.",ties:["naramsin"]},
{id:"t-propaganda",name:"Искусство пропаганды",def:"Образы, показывающие власть и победу, но не поражения.",ch:"На ассирийских рельефах нет ни одного погибшего ассирийца. Гомбрих оговаривается: может быть, действовало и древнее убеждение, что образ есть нечто большее, чем просто образ.",ties:["ashurnasirpal","assyria"]}
];
D.idea="Египет первым создал строгий стиль и держался его три тысячи лет. Искусство здесь служит вечности: пирамиды, портреты и росписи нужны, чтобы душа продолжала жить. Художник изображает не то, как видит, а то, что знает о вещи, по правилам канона. Нарушил эти правила один фараон, Эхнатон. Рядом, в Месопотамии и на Крите, у искусства другие задачи: прославить победу и передать движение.";
D.blocks=[
{t:"Начало непрерывной традиции",s:"Первые опыты главы 1 не продолжены искусством нашего времени. А вот традиция Египта передавалась от мастера к ученику, потом к грекам, а от греков ко всем нам. Поэтому египетское искусство так важно.",e:["egypt"],w:[]},
{t:"Пирамиды: фараон и вечность",s:"Пирамиды рассказывают об обществе, где тысячи людей годами строили гробницу. Фараон считался божеством. Его тело бальзамировали, а в камне помещали подобие, которое «сохраняет жизнь» души.",e:["egypt","giza","t-pyramid","t-mummy"],w:["w31"]},
{t:"Портреты для вечности",s:"Голова из гробницы в Гизе показывает «возвышенную строгость» Старого царства: нет лести и нет мимолётного выражения. Вскоре такие гробницы стали строить и приближённые фараона.",e:["giza"],w:["w32"]},
{t:"Не как видим, а как знаем",s:"Вместо жертвы слуг в гробницы стали класть картины. Египтяне рисуют каждый элемент с самой ясной стороны, как карту: пруд сверху, деревья сбоку. Человеческая фигура получается странно плоской, зато ничего не потеряно.",e:["nebamun","hesira","t-canon","t-hierarchy"],w:["w33","w34"]},
{t:"Гробница Хнумхотепа",s:"Подробный разбор стены: титулы, охота на птиц, рыбная ловля, дары. Рисунок расчерчен сеткой, но в нём точно переданы виды птиц и рыб. Видно, как геометрия и наблюдательность живут вместе.",e:["khnumhotep"],w:["w35","w36","w37"]},
{t:"Стиль и его законы. Книга мёртвых",s:"Стиль — невидимый закон, которому подчиняется всё. Египетский художник учил кодекс правил: позы, цвета, облик богов. Лучшим считался тот, кто мог точнее повторить почитаемые образцы, поэтому стиль менялся очень мало.",e:["anubis","thoth","horus","t-style"],w:["w38"]},
{t:"Эхнатон и революция Амарны",s:"Фараон-еретик ввёл культ Атона и переехал в новый город. Его изображения нарушают каноны: он уродлив, ласков с детьми. Тутанхамон продолжил линию, но потом старые верования вернулись.",e:["akhenaten","nefertiti","aten","tut"],w:["w39","w40","w42"]},
{t:"Крит и Микены: свобода линии",s:"На острове Крит жил народ, чьи мастера «великолепно передавали движение». Раскопки дворца в Кноссе удивили учёных. Возможно, критские образцы позволили египтянам на время отступить от канона.",e:["minoans","knossos","mycenae"],w:["w41"]},
{t:"Месопотамия: от арфы Ура до рельефов Ассирии",s:"В Двуречье строили из необожжённого кирпича, камня мало, поэтому дошло меньше. Зато остались арфа Ура, стела победы Нарам-Суэна и ассирийские рельефы-хроники, где нет ни одного раненого ассирийца.",e:["sumer","ur","naramsin","assyria","ashurnasirpal","nimrud"],w:["w43","w44","w45","wsphinx"]}
];
